const std = @import("std");

pub fn main() !void {
    const score: i32 = 85;

    const grade = if (score >= 90) 'A'
        else if (score >= 80) 'B'
        else if (score >= 70) 'C'
        else if (score >= 60) 'D'
        else 'F';

    std.debug.print("Score: {}, Grade: {c}\n", .{score, grade});
}
